 3 | const MAX_SYSTEM_LOG_LINES = 64;
 4 | 
 5 | export const systemLogAtom = atom<string[]>([]);
 6 | 
 7 | export function appendSystemLog(message: string): void {
 8 |   const time = new Date().toLocaleTimeString('zh-CN', { hour12: false });
 9 |   const line = `[${time}] ${message}`;
10 |   const lines = systemLogAtom.get();
11 |   const next = [...lines, line];
12 |   systemLogAtom.set(
13 |     next.length > MAX_SYSTEM_LOG_LINES ? next.slice(-MAX_SYSTEM_LOG_LINES) : next,
14 |   );
15 | }
16 | 
17 | export function clearSystemLog(): void {
18 |   systemLogAtom.set([]);
19 | }
