  1 | import type Anthropic from '@anthropic-ai/sdk';
  2 | import type { MessageStream } from '@anthropic-ai/sdk/lib/MessageStream.mjs';
  3 | import { agentTurn } from '../agent/turn.js';
  4 | import { messagesAtom } from '../store/conversation.js';
  5 | import { appendSystemLog } from '../store/logAtom.js';
  6 | import { logTextAtom, toolCallsAtom, workingStatusAtom } from '../store/ui-state.js';
  7 | import type { WorkingStatus } from '../store/ui-state.js';
  8 | import { ui } from '../components/ui/index.js';
  9 | import { getToolDisplayText } from '../tools/index.js';
 10 | 
 11 | type StreamingMessage = Anthropic.MessageParam & { status?: 'streaming' };
 12 | 
 13 | export function setupAgentEvents() {
 14 |   let lastStatus: WorkingStatus | null = null;
 15 |   const logBuffers = new Map<string, string[]>();
 16 | 
 17 |   const flushLogBuffer = (toolUseId: string) => {
 18 |     const chunks = logBuffers.get(toolUseId);
 19 |     if (chunks && chunks.length > 0) {
 20 |       logTextAtom.set(logTextAtom.get() + chunks.join(''));
 21 |       logBuffers.delete(toolUseId);
 22 |     }
 23 |   };
 24 | 
 25 |   const clearLogBuffers = () => logBuffers.clear();
 26 | 
 27 |   agentTurn.events.on('stream:create', (stream: MessageStream<null>) => {
 28 |     appendSystemLog('流：创建消息流');
 29 |     let thinkingText = '';
 30 |     let streamingText = '';
 31 |     let textStarted = false;
 32 | 
 33 |     stream.on('thinking', (chunk) => {
 34 |       thinkingText += chunk;
 35 |       logTextAtom.set(thinkingText);
 36 |       workingStatusAtom.set({ type: 'thinking' });
 37 |     });
 38 | 
 39 |     stream.on('text', (chunk) => {
 40 |       if (!textStarted) {
 41 |         textStarted = true;
 42 |         appendSystemLog('流：开始文本输出');
 43 |         toolCallsAtom.set([]);
 44 |         logTextAtom.set('');
 45 |         clearLogBuffers();
 46 |       }
 47 |       workingStatusAtom.set({ type: 'streaming' });
 48 |       streamingText += chunk;
 49 | 
 50 |       const messages = messagesAtom.get() as StreamingMessage[];
 51 |       const streamingIdx = messages.findIndex((msg) => msg.status === 'streaming');
 52 | 
 53 |       const streamingMsg: StreamingMessage = {
 54 |         role: 'assistant' as const,
 55 |         content: streamingText,
 56 |         status: 'streaming',
 57 |       };
 58 | 
 59 |       if (streamingIdx !== -1) {
 60 |         const updated = [...messages];
 61 |         updated[streamingIdx] = streamingMsg;
 62 |         messagesAtom.set(updated);
 63 |       } else {
 64 |         messagesAtom.set([...messages, streamingMsg]);
 65 |       }
 66 |     });
 67 | 
 68 |     stream.on('end', () => {
 69 |       appendSystemLog('流：消息流结束');
 70 |       const messages = messagesAtom.get() as StreamingMessage[];
 71 |       const streamingIdx = messages.findIndex((msg) => msg.status === 'streaming');
 72 |       if (streamingIdx !== -1) {
 73 |         messagesAtom.set(messages.filter((_, i) => i !== streamingIdx));
 74 |       }
 75 |       toolCallsAtom.set([]);
 76 |       logTextAtom.set('');
 77 |       clearLogBuffers();
 78 |     });
 79 |   });
 80 | 
 81 |   agentTurn.events.on('tool:use', ({ toolUseId, toolName, toolInput, completed }) => {
 82 |     const displayText = getToolDisplayText(toolName, toolInput);
 83 |     const existing = toolCallsAtom.get();
 84 |     const idx = existing.findIndex((t) => t.id === toolUseId);
 85 | 
 86 |     if (completed) {
 87 |       appendSystemLog(`工具完成：${toolName}`);
 88 |       flushLogBuffer(toolUseId);
 89 |     } else if (idx === -1) {
 90 |       appendSystemLog(`工具调用：${toolName}`);
 91 |     }
 92 | 
 93 |     if (idx !== -1) {
 94 |       const updated = [...existing];
 95 |       updated[idx] = {
 96 |         ...updated[idx],
 97 |         completed,
 98 |         displayText,
 99 |         status: completed ? undefined : updated[idx].status,
100 |       };
101 |       toolCallsAtom.set(updated);
102 |     } else {
103 |       toolCallsAtom.set([
104 |         ...existing,
105 |         { id: toolUseId, toolName, toolInput, completed, displayText },
106 |       ]);
107 |     }
108 |   });
109 | 
110 |   agentTurn.events.on('tool:slow', ({ toolUseId, elapsedMs }) => {
111 |     const existing = toolCallsAtom.get();
112 |     const idx = existing.findIndex((t) => t.id === toolUseId);
113 |     if (idx !== -1) {
114 |       const updated = [...existing];
115 |       updated[idx] = { ...updated[idx], elapsedMs };
116 |       toolCallsAtom.set(updated);
117 |     }
118 |   });
119 | 
120 |   agentTurn.events.on('status', (status) => {
121 |     if (shouldLogStatus(status, lastStatus)) {
122 |       appendSystemLog(formatStatusLog(status));
123 |     }
124 |     lastStatus = status;
125 | 
126 |     if (status.type === 'connecting') {
127 |       toolCallsAtom.set([]);
128 |       logTextAtom.set('');
129 |       clearLogBuffers();
130 |       ui.MessageBar.clearMessages();
131 |     }
132 | 
133 |     if (status.type === 'calling_tool') {
134 |       const calls = toolCallsAtom.get();
135 |       let changed = false;
136 |       for (const call of calls) {
137 |         if (!call.completed && call.status !== 'executing') {
138 |           call.status = 'executing';
139 |           changed = true;
140 |         }
141 |       }
142 |       if (changed) toolCallsAtom.set([...calls]);
143 |     }
144 | 
145 |     if (status.type === 'idle') {
146 |       clearLogBuffers();
147 |     }
148 | 
149 |     workingStatusAtom.set(status);
150 |   });
151 | 
152 |   agentTurn.events.on('log:chunk', ({ toolUseId, chunk }) => {
153 |     const buf = logBuffers.get(toolUseId) || [];
154 |     buf.push(chunk);
155 |     logBuffers.set(toolUseId, buf);
156 |   });
157 | }
158 | 
159 | function formatStatusLog(status: WorkingStatus): string {
160 |   switch (status.type) {
161 |     case 'idle':
162 |       return '状态：空闲';
163 |     case 'connecting':
164 |       return '状态：连接 API';
165 |     case 'thinking':
166 |       return '状态：思考中';
167 |     case 'streaming':
168 |       return '状态：流式输出';
169 |     case 'calling_tool':
170 |       return status.elapsedMs != null
171 |         ? `状态：执行工具 (${(status.elapsedMs / 1000).toFixed(1)}s)`
172 |         : '状态：执行工具';
173 |     case 'completed':
174 |       return status.elapsedMs != null
175 |         ? `状态：完成 (${(status.elapsedMs / 1000).toFixed(1)}s)`
176 |         : '状态：完成';
177 |     case 'error':
178 |       return `状态：错误${status.message ? ` — ${status.message}` : ''}`;
179 |     default:
180 |       return '状态：未知';
181 |   }
182 | }
183 | 
184 | function shouldLogStatus(status: WorkingStatus, prev: WorkingStatus | null): boolean {
185 |   if (!prev || status.type !== prev.type) return true;
186 |   if (status.type === 'calling_tool' && prev.type === 'calling_tool') {
187 |     return prev.elapsedMs == null && status.elapsedMs != null;
188 |   }
189 |   if (status.type === 'error' && prev.type === 'error') {
190 |     return status.message !== prev.message;
191 |   }
192 |   return false;
193 | }
