 1 | import React from 'react';
 2 | import { Box, Text } from '@anthropic/ink';
 3 | import type Anthropic from '@anthropic-ai/sdk';
 4 | import { C } from '../../data.js';
 5 | import { messagesAtom } from '../../../../store/conversation.js';
 6 | import { useSchedulState } from '../../hooks/useSchedulState.js';
 7 | import { Markdown } from './Markdown.js';
 8 | 
 9 | interface LogMessage extends Anthropic.MessageParam {
10 |   status?: 'streaming' | 'clear';
11 | }
12 | 
13 | function getTextContent(content: Anthropic.MessageParam['content']): string {
14 |   if (typeof content === 'string') return content;
15 |   return content
16 |     .filter((block): block is { type: 'text'; text: string } => block.type === 'text')
17 |     .map((block) => block.text)
18 |     .join('\n');
19 | }
20 | 
21 | interface LogItem {
22 |   id: string | number;
23 |   role: 'user' | 'assistant';
24 |   text: string;
25 |   type?: 'clear';
26 | }
27 | 
28 | export const Conversation = (): React.ReactNode => {
29 |   const messages = useSchedulState(messagesAtom);
30 |   const staticItems = messages.flatMap((raw, i): LogItem[] => {
31 |     const msg = raw as LogMessage;
32 |     if (msg.status === 'clear') {
33 |       return [{ id: i, role: 'user', text: '', type: 'clear' }];
34 |     }
35 |     const text = getTextContent(msg.content);
36 |     if (!text) return [];
37 |     if (msg.role === 'user') {
38 |       return [{ id: i, role: msg.role, text }];
39 |     }
40 |     if (msg.role === 'assistant') {
41 |       return [{ id: i, role: 'assistant', text }];
42 |     }
43 |     return [];
44 |   }) satisfies LogItem[];
45 |   return (
46 |     <Box flexDirection="column">
47 |       {staticItems.map((item: LogItem) => {
48 |         if (item.role === 'user') {
49 |           return (
50 |             <Box key={item.id} paddingX={1} paddingY={1} flexDirection="row">
51 |               <Text color={C.primary}>{'\u258c'}</Text>
52 |               <Box flexGrow={1} paddingLeft={1} paddingRight={1}>
53 |                 <Text bold color={C.primary}>
54 |                   {item.text}
55 |                 </Text>
56 |               </Box>
57 |             </Box>
58 |           );
59 |         }
60 |         return (
61 |           <Box >
62 |             <Markdown>{item.text}</Markdown>
63 |           </Box>
64 |         );
65 |       })}
66 |     </Box>
67 |   );
68 | };
