15 | function formatElapsed(ms: number): string {
16 |   if (ms < 1000) return `${ms}ms`;
17 |   const s = (ms / 1000).toFixed(1);
18 |   if (ms < 60000) return `${s}s`;
19 |   const m = Math.floor(ms / 60000);
20 |   const sec = ((ms % 60000) / 1000).toFixed(0);
21 |   return `${m}m ${sec}s`;
22 | }
23 | 
24 | export function WorkingStatus() {
25 |   const info = useSchedulState(workingStatusAtom);
26 |   const modelValue = useSchedulState(model.atom);
27 |   const effort = useSchedulState(model.effort);
28 |   const contextSize = useSchedulState(contextSizeAtom);
29 |   const dropdownItems = useSchedulState(dropdown.atom);
30 | 
31 |   const hideLeftStatus = dropdownItems.visible && dropdownItems.items.length > 0;
32 | 
33 |   const content = (() => {
34 |     switch (info.type) {
35 |       case 'connecting':
36 |       case 'thinking':
37 |       case 'streaming':
38 |         return (
39 |           <Box>
40 |             <Spin />
41 |             <Text>{info.type}</Text>
42 |           </Box>
43 |         );
44 |       case 'calling_tool':
45 |         return (
46 |           <Box>
47 |             <Spin />
48 |             <Text>{info.type}</Text>
49 |             {info.elapsedMs != null && (
50 |               <Text color={C.dim}> ({formatElapsed(info.elapsedMs)})</Text>
51 |             )}
52 |           </Box>
53 |         );
54 |       case 'error':
55 |         return <Text color={C.error}>✗ {info.message}</Text>;
56 |       case 'completed':
57 |         return (
58 |           <Text color={C.success}>
59 |             ✓ completed{' '}
60 |             {info.elapsedMs != null ? formatElapsed(info.elapsedMs) : 'Done'}
61 |           </Text>
62 |         );
63 |       default:
64 |         return null;
65 |     }
66 |   })();
67 | 
68 |   return (
69 |     <Box flexDirection="row">
70 |       <Box flexGrow={1} flexShrink={1}>
71 |         {hideLeftStatus ? null : content}
72 |       </Box>
73 |       <Box flexShrink={0} paddingRight={4}>
74 |         <Text color={C.dim} wrap="wrap">
75 |           {modelValue} · {effort}{contextSize > 0 ? ` · ${(contextSize / 1000000).toFixed(2)}M tokens` : ''}
76 |         </Text>
77 |       </Box>
78 |     </Box>
79 |   );
80 | }
