  1 | import { Box, Text, useInput } from "@anthropic/ink";
  2 | import React from "react";
  3 | import { useCallback, useState } from "react";
  4 | import { SimpleTextInput } from "./Input";
  5 | import { C } from "../../data";
  6 | import mitt from 'mitt'
  7 | import { useSchedulState } from '../../hooks';
  8 | import { terminalInput, pluginUIsAtom } from '../../../../store/ui-state.js';
  9 | import { DropDownUI } from '../DropDown/index.js';
 10 | 
 11 | type Events = {
 12 |   submit: string
 13 | }
 14 | const emitter = mitt<Events>()
 15 | 
 16 | function TerminalInput() {
 17 |   const [input, setInput] = useState(terminalInput.text.get());
 18 |   const [cursorOffset, setCursorOffset] = useState(0);
 19 |   const [prevInputs, setPrevInputs] = useState<string[]>([]);
 20 |   const [historyIndex, setHistoryIndex] = useState(-1);
 21 |   const columns = process.stdout.columns - 6;
 22 |   const activePluginUIs = useSchedulState(pluginUIsAtom);
 23 | 
 24 |   useInput((_input, key) => {
 25 |     for (const ui of activePluginUIs) {
 26 |       if (ui.onInput?.(_input, key)) {
 27 |         setInput('');
 28 |         setCursorOffset(0);
 29 |         return;
 30 |       }
 31 |     }
 32 |     if (DropDownUI.quickCommand.handleKey(key)) {
 33 |       setInput('');
 34 |       setCursorOffset(0);
 35 |     }
 36 |   });
 37 | 
 38 |   const onSubmit = useCallback(
 39 |     (value: string) => {
 40 |       if (!value.trim()) return;
 41 | 
 42 |       // 下拉菜单可见时的 Enter/Tab/Escape 由 useInput → handleDropdownKey 处理，
 43 |       // 但 SimpleTextInput 也会触发 onSubmit，这里需要防御
 44 |       if (terminalInput.disabled.get()) return;
 45 | 
 46 |       const trimmed = value.trim();
 47 |       setPrevInputs(prev => [...prev, trimmed]);
 48 |       setHistoryIndex(-1);
 49 |       setInput('');
 50 |       setCursorOffset(0);
 51 |       emitter.emit('submit', trimmed);
 52 |     },
 53 |     [],
 54 |   );
 55 | 
 56 |   const onExit = useCallback(() => {
 57 |     process.exit(0);
 58 |   }, []);
 59 | 
 60 |   const handleChange = useCallback((value: string) => {
 61 |     setInput(value);
 62 | 
 63 |     // 检测 '/' 开头 → 委托给 DropDown 模块显示快捷命令列表
 64 |     if (value.startsWith('/') && value.length >= 1) {
 65 |       const query = value.slice(1);
 66 |       DropDownUI.quickCommand.show(query);
 67 |     } else {
 68 |       DropDownUI.quickCommand.hide();
 69 |     }
 70 |   }, []);
 71 | 
 72 |   const onHistoryUp = useCallback(() => {
 73 |     // 下拉菜单可见时，↑↓ 由 useInput → handleDropdownKey 处理
 74 |     if (terminalInput.disabled.get()) return;
 75 |     if (prevInputs.length === 0) return;
 76 |     const newIndex = historyIndex < prevInputs.length - 1 ? historyIndex + 1 : historyIndex;
 77 |     if (newIndex !== historyIndex) {
 78 |       setHistoryIndex(newIndex);
 79 |       const val = prevInputs[prevInputs.length - 1 - newIndex]!;
 80 |       setInput(val);
 81 |       setCursorOffset(val.length);
 82 |     }
 83 |   }, [historyIndex, prevInputs]);
 84 | 
 85 |   const onHistoryDown = useCallback(() => {
 86 |     // 下拉菜单可见时，↑↓ 由 useInput → handleDropdownKey 处理
 87 |     if (terminalInput.disabled.get()) return;
 88 |     if (historyIndex > 0) {
 89 |       const newIndex = historyIndex - 1;
 90 |       setHistoryIndex(newIndex);
 91 |       const val = prevInputs[prevInputs.length - 1 - newIndex]!;
 92 |       setInput(val);
 93 |       setCursorOffset(val.length);
 94 |     } else if (historyIndex === 0) {
 95 |       setHistoryIndex(-1);
 96 |       setInput('');
 97 |       setCursorOffset(0);
 98 |     }
