 1 | import { atom, onMount, type WritableAtom } from 'nanostores';
 2 | import { readFile, writeFile, mkdir } from 'node:fs/promises';
 3 | import { resolve } from 'node:path';
 4 | import { homedir } from 'node:os';
 5 | 
 6 | const CONFIG_PATH = resolve(homedir(), '.mica', 'config.json');
 7 | 
 8 | interface PersistedData {
 9 |   [key: string]: unknown;
10 | }
11 | 
12 | let writeTimer: ReturnType<typeof setTimeout> | null = null;
13 | let pendingData: PersistedData | null = null;
14 | let loadedData: PersistedData | null = null;
15 | 
16 | async function loadAll(): Promise<PersistedData> {
17 |   if (loadedData) return loadedData;
18 |   try {
19 |     const raw = await readFile(CONFIG_PATH, 'utf-8');
20 |     loadedData = JSON.parse(raw);
21 |   } catch {
22 |     loadedData = {};
23 |   }
24 |   return loadedData!;
25 | }
26 | 
27 | function scheduleSave() {
28 |   if (writeTimer) clearTimeout(writeTimer);
29 |   writeTimer = setTimeout(async () => {
30 |     if (!pendingData) return;
31 |     const data = pendingData;
32 |     pendingData = null;
33 |     try {
34 |       await mkdir(resolve(homedir(), '.mica'), { recursive: true });
35 |       const existing = await loadAll();
36 |       const merged = { ...existing, ...data };
37 |       loadedData = merged;
38 |       await writeFile(CONFIG_PATH, JSON.stringify(merged, null, 2), 'utf-8');
39 |     } catch {
40 |       // silent
41 |     }
42 |   }, 500);
43 | }
44 | 
45 | export function createPersistedAtom<T>(key: string, defaultValue: T): WritableAtom<T> {
46 |   const store = atom<T>(defaultValue);
47 | 
48 |   onMount(store, () => {
49 |     loadAll().then((data) => {
50 |       if (key in data) {
51 |         store.set(data[key] as T);
52 |       }
53 |     });
54 | 
55 |     return store.subscribe((value) => {
56 |       if (!pendingData) pendingData = {};
57 |       pendingData[key] = value;
58 |       scheduleSave();
59 |     });
60 |   });
61 | 
62 |   return store;
63 | }
