  9 | import { getClient } from './client.js';
 10 | import { clearBackups } from '../utils/fileHistory.js';
 11 | import mitt from 'mitt';
 12 | 
 13 | export type AgentTurnEvents = {
 14 |   'stream:create': MessageStream<null>;
 15 |   'tool:use': {
 16 |     toolUseId: string;
 17 |     toolName: string;
 18 |     toolInput: Record<string, any>;
 19 |     completed: boolean;
 20 |   };
 21 |   'tool:slow': {
 22 |     toolUseId: string;
 23 |     elapsedMs: number;
 24 |   };
 25 |   status: WorkingStatus;
 26 |   'log:chunk': { toolUseId: string; chunk: string };
 27 | };
 28 | 
 29 | export interface IterationResult {
 30 |   hasToolUse: boolean;
 31 |   wasTruncated: boolean;
 32 |   finalMessage: Anthropic.Message;
 33 | }
 34 | 
 35 | export type RunFn = (
 36 |   userInput: string,
 37 |   onIteration?: (result: IterationResult) => void,
 38 | ) => Promise<void>;
 39 | export type Middleware = (
 40 |   userInput: string,
 41 |   next: RunFn,
 42 |   onIteration?: (result: IterationResult) => void,
 43 | ) => Promise<void>;
 44 | 
 45 | class AgentTurn {
 46 |   readonly events = mitt<AgentTurnEvents>();
 47 | 
 48 |   private middlewares: Middleware[] = [];
 49 | 
 50 |   use(middleware: Middleware) {
 51 |     this.middlewares.push(middleware);
 52 |   }
 53 | 
 54 |   async executeSingleIteration(): Promise<IterationResult> {
 55 |     const messages = messagesAtom.get();
 56 |     const modelName = model.atom.get();
 57 |     const effort = model.effort.get();
 58 | 
 59 |     appendSystemLog(`迭代开始：model=${modelName} effort=${effort}`);
 60 |     this.events.emit('status', { type: 'connecting' });
 61 | 
 62 |     const stream = getClient().messages.stream({
 63 |       model: modelName,
 64 |       max_tokens: model.maxTokens.get(),
 65 |       system: systemPrompt,
 66 |       messages,
 67 |       thinking:
 68 |         effort === 'none'
 69 |           ? { type: 'disabled' as const }
 70 |           : { type: 'enabled' as const, budget_tokens: EFFORT_TOKENS[effort] },
 71 |       output_config: effort !== 'none' ? { effort } : undefined,
 72 |       tools: toolDefinitions,
 73 |     }) as MessageStream<null>;
 74 | 
 75 |     this.events.emit('stream:create', stream);
 76 | 
 77 |     let hasToolUse = false;
 78 |     const completedToolUses: Array<{ id: string; name: string; input: Record<string, any> }> = [];
 79 |     stream.on('contentBlock', (content) => {
 80 |       if (content.type === 'tool_use') {
 81 |         hasToolUse = true;
 82 |         const tool = {
 83 |           id: content.id,
 84 |           name: content.name,
 85 |           input: content.input as Record<string, any>,
 86 |         };
 87 |         completedToolUses.push(tool);
 88 |         this.events.emit('tool:use', {
 89 |           toolUseId: tool.id,
 90 |           toolName: tool.name,
 91 |           toolInput: tool.input,
 92 |           completed: false,
 93 |         });
 94 |       }
 95 |     });
 96 | 
 97 |     const finalMessage = await stream.finalMessage();
 98 |     const wasTruncated = finalMessage.stop_reason === 'max_tokens';
 99 |     messagesAtom.set([...messages, finalMessage]);
100 |     appendSystemLog(
101 |       `迭代响应：${completedToolUses.length > 0 ? `${completedToolUses.length} 个工具调用` : '无工具调用'}${wasTruncated ? ' [因 max_tokens 截断]' : ''}`,
102 |     );
103 | 
104 |     if (completedToolUses.length > 0) {
105 |       const toolStartTime = Date.now();
106 |       this.events.emit('status', { type: 'calling_tool' });
107 | 
108 |       const timer = setInterval(() => {
109 |         this.events.emit('status', {
110 |           type: 'calling_tool',
111 |           elapsedMs: Date.now() - toolStartTime,
112 |         });
113 |       }, 200);
114 | 
115 |       const SLOW_TOOL_THRESHOLD_MS = 3000;
116 |       const toolTimers = new Map<string, { name: string; startTime: number; lastLogTime: number }>();
117 |       const slowToolTimer = setInterval(() => {
118 |         const now = Date.now();
119 |         for (const [id, info] of toolTimers) {
120 |           const elapsed = now - info.startTime;
121 |           if (elapsed >= SLOW_TOOL_THRESHOLD_MS && now - info.lastLogTime >= SLOW_TOOL_THRESHOLD_MS) {
122 |             this.events.emit('tool:slow', { toolUseId: id, elapsedMs: elapsed });
123 |             info.lastLogTime = now;
124 |           }
125 |         }
126 |       }, SLOW_TOOL_THRESHOLD_MS);
127 | 
128 |       const toolResults: Anthropic.ToolResultBlockParam[] = [];
129 |       const settled = await Promise.allSettled(
130 |         completedToolUses.map(async (tool) => {
131 |           const startTime = Date.now();
132 |           toolTimers.set(tool.id, { name: tool.name, startTime, lastLogTime: 0 });
133 |           const result = await executeTool(tool.name, tool.input, {
134 |             onChunk: (chunk) => {
135 |               this.events.emit('log:chunk', { toolUseId: tool.id, chunk });
136 |             },
137 |           });
138 |           const elapsed = Date.now() - startTime;
139 |           toolTimers.delete(tool.id);
140 |           if (elapsed >= SLOW_TOOL_THRESHOLD_MS) {
141 |             appendSystemLog(`工具 ${tool.name} 执行完成，耗时 ${(elapsed / 1000).toFixed(1)}s`);
142 |           }
143 |           this.events.emit('tool:slow', { toolUseId: tool.id, elapsedMs: elapsed });
144 |           const records = sessionToolRecordsAtom.get();
145 |           sessionToolRecordsAtom.set([...records, { toolName: tool.name, toolInput: tool.input, elapsedMs: elapsed }]);
146 |           return { tool, result };
147 |         }),
148 |       );
149 | 
150 |       clearInterval(timer);
151 |       clearInterval(slowToolTimer);
152 | 
153 |       for (let i = 0; i < settled.length; i++) {
154 |         const item = settled[i];
155 |         const tool = completedToolUses[i];
156 |         const result =
157 |           item.status === 'fulfilled'
158 |             ? item.value.result
159 |             : `工具 ${tool.name} 执行异常：\n${
160 |                 item.reason instanceof Error
161 |                   ? `${item.reason.name}: ${item.reason.message}`
162 |                   : String(item.reason)
163 |               }`;
164 |         toolResults.push({ type: 'tool_result', tool_use_id: tool.id, content: result });
165 | 
166 |         this.events.emit('tool:use', {
167 |           toolUseId: tool.id,
168 |           toolName: tool.name,
169 |           toolInput: tool.input,
170 |           completed: true,
171 |         });
172 | 
173 |         if (item.status === 'rejected') {
174 |           this.events.emit('status', {
175 |             type: 'error',
176 |             message: item.reason instanceof Error ? item.reason.message : String(item.reason),
177 |           });
178 |         }
179 |       }
180 | 
181 |       const withToolResults = [
182 |         ...messagesAtom.get(),
183 |         { role: 'user', content: toolResults } as Anthropic.MessageParam,
184 |       ];
185 |       messagesAtom.set(withToolResults);
186 |       this.events.emit('status', { type: 'idle' });
187 |     } else {
188 |       this.events.emit('status', { type: 'idle' });
189 |     }
190 |     return { hasToolUse, wasTruncated, finalMessage };
191 |   }
192 | 
193 |   private async _coreRun(userInput: string, onIteration?: (result: IterationResult) => void) {
194 |     appendSystemLog('Agent run 开始');
195 |     sessionToolRecordsAtom.set([]);
196 |     await clearBackups();
197 |     const updated = [...messagesAtom.get(), { role: 'user', content: userInput } as Anthropic.MessageParam];
198 |     messagesAtom.set(updated);
199 |     while (true) {
200 |       const result = await this.executeSingleIteration();
201 |       onIteration?.(result);
202 |       if (!result.hasToolUse && !result.wasTruncated) {
203 |         appendSystemLog('Agent run 结束（无待执行工具）');
204 |         return;
205 |       }
206 |       appendSystemLog(`继续下一轮迭代（${result.wasTruncated ? '响应被截断' : '存在工具调用'}）`);
207 |     }
208 |   }
