210 |   async run(userInput: string, onIteration?: (result: IterationResult) => void) {
211 |     const coreRun: RunFn = this._coreRun.bind(this);
212 |     const chain = this.middlewares.reduceRight<RunFn>(
213 |       (next, mw) => (input, cb) => mw(input, next, cb),
214 |       coreRun,
215 |     );
216 |     return chain(userInput, onIteration);
217 |   }
