 39 | export abstract class MicaPlugin {
 40 |   agent!: IMicaAgent;
 41 | 
 42 |   atoms!: PluginAtoms;
 43 | 
 44 |   private _activeUIId: string | null = null;
 45 |   constructor() {
 46 |     dropdown.atom.listen((state) => {
 47 |       if (state.visible) this.hideUI();
 48 |     });
 49 |   }
 50 |   abstract onInstall(): void | Promise<void>;
 51 | 
 52 |   protected addQuickCommand(command: Command): void {
 53 |     quickCommandsAtom.set([...quickCommandsAtom.get(), command]);
 54 |   }
 55 | 
 56 |   protected showUI(
 57 |     render: () => React.ReactNode,
 58 |     onInput?: (input: string, key: any) => boolean,
 59 |   ): void {
 60 |     const id = this._activeUIId ?? `plugin-ui-${uuid()}`;
 61 |     this._activeUIId = id;
 62 |     const entry: PluginUI = { id, render, onInput };
 63 |     pluginUIsAtom.set([...pluginUIsAtom.get().filter((u) => u.id !== id), entry]);
 64 |   }
 65 | 
 66 |   protected hideUI(): void {
 67 |     if (!this._activeUIId) return;
 68 |     pluginUIsAtom.set(pluginUIsAtom.get().filter((u) => u.id !== this._activeUIId));
 69 |     this._activeUIId = null;
 70 |   }
 71 | 
 72 |   /** 显示一条消息（通过 UI 组件事件），默认 3s 后自动清除 */
 73 |   protected showMessage(text: string, delay: number = 3000): string {
 74 |     const msgId = `msg-${uuid()}`;
 75 |     this.agent.ui.MessageBar.addMessage({ id: msgId, text });
 76 |     if (delay) {
 77 |       setTimeout(() => {
 78 |         this.removeMessage(msgId);
 79 |       }, delay);
 80 |     }
 81 |     return msgId;
 82 |   }
 83 | 
 84 |   /** 移除指定 ID 的消息 */
 85 |   protected removeMessage(id: string): void {
 86 |     this.agent.ui.MessageBar.removeMessage(id);
 87 |   }
 88 | 
 89 |   /** 清除所有消息 */
 90 |   protected clearMessages(): void {
 91 |     this.agent.ui.MessageBar.clearMessages();
 92 |   }
 93 | 
