18 |   private async _generateTitle() {
19 |     const currentId = this.atoms.currentSessionId.get();
20 |     if (!currentId) {
21 |       this.showMessage('没有活跃的会话');
22 |       return;
23 |     }
24 | 
25 |     const messages = this.atoms.messages.get().filter((m: any) => m.status !== 'clear');
26 |     if (messages.length === 0) {
27 |       this.showMessage('没有对话内容');
28 |       return;
29 |     }
30 | 
31 |     this.showUI(() => (
32 |       <Box paddingX={1}>
33 |         <Spin />
34 |         <Text dimColor> 正在生成标题...</Text>
35 |       </Box>
36 |     ));
37 | 
38 |     try {
39 |       const client = getClient();
40 |       const modelName = this.atoms.model.get();
41 | 
42 |       const conversationPreview = messages
43 |         .slice(0, 6)
44 |         .map((m) => `${m.role}: ${typeof m.content === 'string' ? m.content.slice(0, 200) : '[tool calls]'}`)
45 |         .join('\n');
46 | 
47 |       const res = await client.messages.create({
48 |         model: modelName,
49 |         max_tokens: 50,
50 |         system: '你是一个会话命名助手。根据对话内容生成一个简洁的中文标题（不超过20字），只回复标题本身，不要加引号、标点或其他内容。如果不确定，回复"未命名会话"。',
51 |         messages: [
52 |           { role: 'user', content: `请为以下对话生成标题：\n${conversationPreview}` },
53 |         ],
54 |       });
55 | 
56 |       const title =
57 |         (res.content[0]?.type === 'text' ? res.content[0].text.trim() : '') ||
58 |         '未命名会话';
59 | 
60 |       const idx = this.atoms.sessionsIndex.get();
61 |       const updated = idx.map((s) =>
62 |         s.id === currentId ? { ...s, title, updatedAt: Date.now() } : s,
63 |       );
64 |       this.atoms.sessionsIndex.set(updated);
65 |       this.showMessage(`标题已更新: ${title}`);
66 |     } catch (error) {
67 |       const errMsg = error instanceof Error ? error.message : String(error);
68 |       this.showMessage(`生成失败: ${errMsg}`);
69 |     } finally {
70 |       this.hideUI();
71 |     }
